* Stimulus for AC open loop simulation
Vin vp 0 dc 0.9 ac 1

* Control Block
.control
save all

* 1. Operating Point
op
let idd_total = -i(VDD)
let p_dc = idd_total * 1.8
print idd_total p_dc

* 2. AC Open-Loop Frequency Response
ac dec 100 10 1G
let aol_db = vdb(Vout)
let phase_deg = 180/PI * cph(v(Vout))

* Measure DC Gain at 10 Hz
meas ac A_OLDC find aol_db at=10

* Measure 3-dB frequency
let target_3db = A_OLDC - 3
meas ac f_3dB when aol_db=target_3db fall=1

* Measure Unity-Gain Frequency
meas ac f_un when aol_db=0 fall=1

* Measure Phase Margin
meas ac phase_at_fun find phase_deg when aol_db=0 fall=1
let PM = 180 + phase_at_fun
print PM

quit
.endc
.end

